# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">GİZLİ DAVET DÖNEMİ (3 YIL), İLK MÜSLÜMANLAR VE DÂRÜLERKAM (SYR.10.2.1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">İLK DÖRT MÜSLÜMAN (SÂBİKÛN-I EVVELÛN)</text>\n  <text x="35" y="88" font-size="10.8" fill="#1e3a8a">• Müddessir suresi 1-5. ayetlerle tebliğ başladı:</text>\n  <text x="45" y="106" font-size="10.8" font-weight="bold" fill="#1e3a8a">1. Hz. Hatice (r.a.) — İlk iman eden insan/kadın</text>\n  <text x="45" y="126" font-size="10.8" font-weight="bold" fill="#1e3a8a">2. Hz. Ali (r.a.) — İlk iman eden çocuk/genç</text>\n  <text x="45" y="146" font-size="10.8" font-weight="bold" fill="#1e3a8a">3. Hz. Zeyd b. Hârise (r.a.) — İlk azatlı köle</text>\n  <text x="45" y="166" font-size="10.8" font-weight="bold" fill="#1e3a8a">4. Hz. Ebû Bekir (r.a.) — İlk hür yetişkin erkek</text>\n  <text x="35" y="190" font-size="10.5" fill="#1e3a8a">• Hz. Ebû Bekir\'in davetiyle: Osman, Zübeyr, Talha,</text>\n  <text x="45" y="205" font-size="10.5" fill="#1e3a8a">Abdurrahman b. Avf ve Sa\'d b. Ebî Vakkâs.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">DÂRÜLERKAM (ERKAM\'IN EVİ)</text>\n  <text x="370" y="90" font-size="10.8" fill="#14532d">• Safâ Tepesi eteklerinde genç sahabi</text>\n  <text x="380" y="106" font-size="10.8" font-weight="bold" fill="#14532d">Erkam b. Ebü\'l-Erkam\'ın (r.a.) evi.</text>\n  <text x="370" y="130" font-size="10.8" fill="#14532d">• İslam tarihinin ilk eğitim, irşad ve tebliğ</text>\n  <text x="380" y="146" font-size="10.8" fill="#14532d">merkezi (ilk medrese/karargâh).</text>\n  <text x="370" y="170" font-size="10.8" fill="#14532d">• İnen ayetlerin ezberlenip yazıldığı, birlikte</text>\n  <text x="380" y="186" font-size="10.8" fill="#14532d">namaz kılınıp yeni gelenlerin İslam\'a girdiği</text>\n  <text x="380" y="202" font-size="10.8" fill="#14532d">güvenli merkez (Hz. Ömer\'in İslam\'a girişine dek).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Gizli davet (610-613), müşriklerin ani saldırısını önlemiş ve sağlam bir çekirdek kadro yetiştirmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">AÇIK DAVETİN BAŞLAMASI: AKRABALARA VE MEKKE HALKINA ÇAĞRI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. YAKIN AKRABALARI UYARMA (ŞUARÂ, 214)</text>\n  <text x="35" y="90" font-size="10.8" fill="#78350f">• Ayet: "(Ey Muhammed!) Önce en yakın</text>\n  <text x="45" y="106" font-size="10.8" font-weight="bold" fill="#78350f">akrabalarını (aşiretini) uyar!" (Şuarâ, 214)</text>\n  <text x="35" y="130" font-size="10.8" fill="#78350f">• Haşimoğulları (Abdülmuttaliboğulları) yemekli</text>\n  <text x="45" y="146" font-size="10.5" fill="#78350f">toplantıya davet edildi (~45 kişi).</text>\n  <text x="35" y="170" font-size="10.8" fill="#78350f">• Hz. Ali destek verirken, Ebû Tâlib "Seni</text>\n  <text x="45" y="186" font-size="10.5" fill="#78350f">koruyacağım" dedi; Ebû Leheb ise karşı çıktı.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">2. GENEL AÇIK DAVET (HİCR, 94) VE SAFÂ TEPESİ</text>\n  <text x="370" y="90" font-size="10.8" fill="#581c87">• Ayet: "Sana emrolunanı açıkça söyle ve</text>\n  <text x="380" y="106" font-size="10.8" font-weight="bold" fill="#581c87">müşriklere aldırış etme!" (Hicr, 94)</text>\n  <text x="370" y="130" font-size="10.8" fill="#581c87">• Safâ Tepesi\'nde Kureyş boylarına sesleniş:</text>\n  <text x="380" y="146" font-size="10.5" fill="#581c87">"Şu dağın arkasında düşman var desem inanır</text>\n  <text x="380" y="162" font-size="10.5" fill="#581c87">mısınız?" ⟶ "Evet, sen el-Emîn\'sin!"</text>\n  <text x="370" y="186" font-size="10.8" fill="#581c87">• Ebû Leheb\'in hakareti üzerine Tebbet suresi indi.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Safâ Tepesi konuşmasında Hz. Peygamber (s.a.v.) "Kızım Fâtıma! Seni de Allah\'ın azabından kurtaramam" buyurmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MEKKELİ MÜŞRİKLERİN İTİRAZ NEDENLERİ VE BASKI YÖNTEMLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">MÜŞRİKLERİN İTİRAZ NEDENLERİ</text>\n  <text x="35" y="88" font-size="10.8" fill="#881337">• 1. Atalar Dini Bağnazlığı: Putperest geleneği</text>\n  <text x="45" y="104" font-size="10.5" fill="#881337">bırakmak istememeleri ("Atalarımızı böyle bulduk").</text>\n  <text x="35" y="124" font-size="10.8" fill="#881337">• 2. Siyasi ve Ekonomik Çıkar: Kâbe\'deki putlar</text>\n  <text x="45" y="140" font-size="10.5" fill="#881337">üzerinden sağlanan ticari ve siyasi nüfuz kaygısı.</text>\n  <text x="35" y="160" font-size="10.8" fill="#881337">• 3. Sınıf Eşitliği: Köle ile efendinin eşit olması.</text>\n  <text x="35" y="180" font-size="10.8" fill="#881337">• 4. Ahiret İnkârı ve Kabile Rekabeti (Ümeyye-Haşim).</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">UYGULANAN ENGELLEME YÖNTEMLERİ</text>\n  <text x="370" y="88" font-size="10.8" fill="#7c2d12">• Alay ve İftira: Sihirbaz, şair, kâhin, mecnun,</text>\n  <text x="380" y="104" font-size="10.5" fill="#7c2d12">"eskilerin masalları (esâtîru\'l-evvelîn)" suçlaması.</text>\n  <text x="370" y="126" font-size="10.8" fill="#7c2d12">• Uzlaşma ve Rüşvet Teklifleri: Servet, liderlik</text>\n  <text x="380" y="142" font-size="10.5" fill="#7c2d12">veya "bir yıl senin ilahına, bir yıl bizimkine" (Kâfirûn).</text>\n  <text x="370" y="164" font-size="10.8" fill="#7c2d12">• İşkence ve Boykot: Bilâl-i Habeşî, Habbâb b. Eret,</text>\n  <text x="380" y="180" font-size="10.5" fill="#7c2d12">ilk şehitler Hz. Sümeyye ve Hz. Yâsir; 3 yıllık boykot.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hz. Peygamber\'in cevabı: "Güneşi sağ elime, ayı sol elime koysalar vallahi bu davadan vazgeçmem!"</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
